INSERT INTO enum_versions (enum_versions_id, enum, version, schema_url, title, description, default_symbol, status, created, raw_json, last_modified, promoted_at)
VALUES ('8fcba2c8-a9fd-5afd-58b0-cf30be117a45', 'relay.open.or.closed', '000', 'https://schemas.electricity.works/enums/relay.open.or.closed/000', 'relay.open.or.closed', 'Binary state of a single-pole relay contact. Describes whether the relay 
contact is open (not conducting) or closed (conducting), regardless of 
coil energization state.

Note 1: The coil energization required to achieve a contact state depends 
on relay type:
- Normally Open (NO) relay: energized coil → closed contact
- Normally Closed (NC) relay: de-energized coil → closed contact

Note 2: This enum is specifically for single-pole relays with binary states.
Other relay configurations (double-throw, multi-position, latching, etc.) 
require different state enumerations that capture their specific switching 
patterns.
', 'RelayClosed', NULL, '2025-10-14T16:07:00Z', NULL, NULL, NULL) ON CONFLICT (enum_versions_id) DO NOTHING;

