INSERT INTO enum_versions (enum_versions_id, enum, version, schema_url, title, description, default_symbol, status, created, raw_json, last_modified, promoted_at)
VALUES ('6a452bf7-44a8-79cc-343f-5e4fbb75d576', 'spaceheat.telemetry.name', '006', 'https://schemas.electricity.works/enums/spaceheat.telemetry.name/006', 'spaceheat.telemetry.name', 'Specifies the canonical name of telemetry values produced by legacy Spaceheat SCADA systems.
This enum historically encoded both physical quantity and unit scaling within a single string (e.g., WaterTempCTimes1000, GpmTimes100). It remains supported for backward compatibility and stable integration with existing deployed systems.
Newer Sema vocabulary separates quantity classification (gw1.quantity) from unit representation (gw1.unit) to make dimensional semantics explicit and mechanically verifiable. Future designs SHOULD prefer those explicit fields over introducing new values into this enum.
This enum remains authoritative for existing Spaceheat channel definitions but is not intended to expand indefinitely.
', 'Unknown', NULL, '2025-09-24T14:28:00Z', NULL, NULL, NULL) ON CONFLICT (enum_versions_id) DO NOTHING;

INSERT INTO enum_versions (enum_versions_id, enum, version, schema_url, title, description, default_symbol, status, created, raw_json, last_modified, promoted_at)
VALUES ('b5de4fcf-9602-8823-84d1-320d69792436', 'spaceheat.telemetry.name', '007', 'https://schemas.electricity.works/enums/spaceheat.telemetry.name/007', 'spaceheat.telemetry.name', 'Specifies the canonical name of telemetry values produced by legacy Spaceheat SCADA systems.
This enum historically encoded both physical quantity and unit scaling within a single string (e.g., WaterTempCTimes1000, GpmTimes100). It remains supported for backward compatibility and stable integration with existing deployed systems.
Newer Sema vocabulary separates quantity classification (gw1.quantity) from unit representation (gw1.unit) to make dimensional semantics explicit and mechanically verifiable. Future designs SHOULD prefer those explicit fields over introducing new values into this enum.
This enum remains authoritative for existing Spaceheat channel definitions but is not intended to expand indefinitely.
', 'Unknown', NULL, '2026-03-30T17:12:00Z', NULL, NULL, NULL) ON CONFLICT (enum_versions_id) DO NOTHING;

INSERT INTO enum_versions (enum_versions_id, enum, version, schema_url, title, description, default_symbol, status, created, raw_json, last_modified, promoted_at)
VALUES ('310fda22-1dd6-23aa-a816-fd9ed2b22273', 'spaceheat.unit', '001', 'https://schemas.electricity.works/enums/spaceheat.unit/001', 'spaceheat.unit', 'Canonical measurement unit used by legacy Spaceheat SCADA channel configuration and telemetry payloads.
', 'Unknown', NULL, '2024-09-02T15:00:00Z', '{"x-gridworks-extended_description": "This enum is used in component ChannelConfig objects, where it is paired with an Exponent field to express the serialized unit and scaling of a telemetry channel.\nIt is a legacy Spaceheat unit vocabulary. In the near future it is expected to be replaced by a new layout mechanism based on gw1.unit.\n"}', NULL, NULL) ON CONFLICT (enum_versions_id) DO NOTHING;

