INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('18d6e38b-f44b-7517-7c94-301e384786d3', 'base.g.node.class/000', 'TerminalAsset', 0, 'A physical transactive asset such as a heat pump, hot water heater, residential battery,  electric vehicle, or any other end-use device located behind an atomic metered point.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('6745ef12-48d0-2a28-4d8c-ae75fd33497b', 'base.g.node.class/000', 'LeafTransactiveNode', 1, 'The atomic metered unit of the grid. Represents the smallest indivisible metering boundary capable of participating in markets or entering Dispatch Contracts on behalf of a TerminalAsset. Every TerminalAsset is associated with exactly one LeafTransactiveNode.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('95a13f6a-e62b-dcc1-d97d-a7696f17dc77', 'base.g.node.class/000', 'ConnectivityNode', 2, 'A physical topological node in the electric power system where conductors join, split, or change configuration. Conceptually aligned with the ConnectivityNode in the IEC 61970/61968 CIM (Common Information Model), but simplified for distribution-level modeling and OPF applications.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('40194eae-2b2d-6a48-6caa-101592672c14', 'base.g.node.class/000', 'MarketMaker', 3, 'A physical constraint point in the conductor topology that requires localized market coordination. Identified as a grid location (e.g., feeder constraint, transformer limit) where a MarketMaker actor computes local prices for balancing and constraint compliance. See [market-maker](https://gridworks.readthedocs.io/en/latest/market-maker.html).
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('63c9da81-dc04-c0c1-138e-615c3111cb78', 'base.g.node.class/000', 'Logical', 4, 'A non-physical Grid Node whose identity carries no inherent conductor-topology or metering semantics. Used for purely logical or service-level nodes such as SCADA, forecasting services, market-maker actors, simulation nodes, or organizational microservices. Logical nodes may coordinate with or operate on physical nodes, but do not themselves represent physical grid structure.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('8724c5d8-7c3d-56ec-2a16-aab16673806e', 'buffer.regulation.mode/000', 'Normal', 0, 'Normal mode uses the full range of the buffer thermal store. Charging begins when the buffer is declared empty, as determined by the lowest available buffer temperature sensor dropping below a threshold temperature. The buffer is declared full when the highest buffer temperature sensor rises above a threshold temperature. Thresholds are derived from required source water temperature calculations that account for house performance and weather forecasts.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('4f897428-43b0-ffab-7579-6abf01698b4b', 'buffer.regulation.mode/000', 'Tight', 1, 'Tight mode keeps the buffer within a narrowly regulated temperature band, permitting frequent charge and discharge transitions to maintain relatively constant buffer energy. Heat pump short-cycling is prevented by alternating between charging the buffer and the store.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('5b5818c0-7a70-7659-0eca-a1283217b621', 'change.heatcall.source/000', 'WallThermostat', 0, 'Heat call is controlled by the local wall thermostat.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
