VALUES ('66284975-2f85-5a0f-6a3b-6a4093fe07c6', 'g.node.instance.status/000', 'Ended', 2, 'This runtime instance terminated cleanly and voluntarily relinquished authority. Ended indicates normal shutdown rather than conflict resolution or forced revocation.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('aba0a36e-b505-95b6-1e27-ddd6047edab3', 'g.node.instance.transport/000', 'RabbitAmqp', 0, 'The instance connected using the AMQP protocol over RabbitMQ, typically via TLS on port 5671.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('b42b0e19-460e-b394-c4ed-b36f2070a2f5', 'g.node.instance.transport/000', 'RabbitMqtt', 1, 'The instance connected using the MQTT protocol over RabbitMQ, typically via TLS on port 8883 or 1883 depending on configuration.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('38dd3b0d-6431-15b4-9e7b-f090f706f659', 'g.node.status/000', 'Pending', 0, 'The GNode has been created but is not yet authorized to participate in system coordination.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('bb93bf14-ef24-8268-60af-50b0a7d5fc9c', 'g.node.status/000', 'Active', 1, 'The GNode is authorized to participate in system coordination.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('34cb3a88-b8c4-0739-810e-92a34b0bf9c1', 'g.node.status/000', 'Suspended', 2, 'The GNode is temporarily disabled. It retains identity but does not participate in active coordination. A Suspended GNode MAY transition back to Active.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('1e3b2c93-62b2-8127-14a1-1bcd48c7720a', 'g.node.status/000', 'PermanentlyDeactivated', 3, 'The GNode has been permanently retired and does not participate in active coordination. It may not change back to another state.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('de5be556-8ffb-5bb6-b577-a7bde34605c2', 'gpm.from.hz.method/000', 'Constant', 0, 'Apply a fixed conversion relationship from frequency to gallons per minute.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('d1d9e6af-f31c-e35c-0d03-d3745371c423', 'gw.g.node.class/000', 'Unknown', 0, 'A GNode whose class has not yet been assigned.') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('76a34a24-3382-5451-7abd-73fd5fe3303c', 'gw.g.node.class/000', 'TerminalAsset', 1, 'A physical transactive asset such as a heat pump, hot water heater, residential battery,  electric vehicle, or any other end-use device located behind an atomic metered point.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('b5855677-7823-fcf1-05b6-1ec24066c2cf', 'gw.g.node.class/000', 'ConnectivityNode', 2, 'A physical topological node in the electric power system where conductors join, split, or change configuration. Conceptually aligned with the ConnectivityNode in the IEC 61970/61968 CIM (Common Information Model), but simplified for distribution-level modeling and OPF applications.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('9d4733b9-1f81-74b3-2360-d82720769c6e', 'gw.g.node.class/000', 'LeafTransactiveNode', 3, 'The atomic metered unit of the grid. Represents the smallest indivisible metering boundary capable of participating in markets or entering Dispatch Contracts on behalf of a TerminalAsset. Every TerminalAsset is associated with exactly one LeafTransactiveNode.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('ebfae846-d22c-e905-edc0-e10dce1e1b20', 'gw.g.node.class/000', 'MarketMaker', 4, 'A physical constraint point in the conductor topology that requires localized market coordination. Identified as a grid location (e.g., feeder constraint, transformer limit) where a MarketMaker actor computes local prices for balancing and constraint compliance. See [market-maker](https://gridworks.readthedocs.io/en/latest/market-maker.html).
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('79d9bbc9-ca76-e30f-ccd5-fdf8348908c2', 'gw.g.node.class/000', 'Scada', 5, 'A GNode responsible for local telemetry, data acquisition, and control of a TerminalAsset.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('161dd389-466a-337f-fc62-59b478068200', 'gw.g.node.class/000', 'PriceForecastService', 6, 'A service that provides forward price projections for planning, bidding, or dispatch optimization.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('e13adb9f-70c5-db15-1f47-23d104e7f2e9', 'gw.g.node.class/000', 'WeatherForecastService', 7, 'A service that provides meteorological forecasts used for load and generation prediction.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('38c2c795-cdd4-184a-7061-f62834585614', 'gw.g.node.class/000', 'TimeCoordinator', 8, 'A service responsible for maintaining simulation time or orchestrated  test time across actors.
