INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('0206bbf9-40c8-ad67-facf-e5d7d5b4a458', 'gw1.seasonal.storage.mode/000', 'BufferOnly', 1, 'Operate using only the buffer tank.
