INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('d42a1c51-bbb2-0db3-6cc1-703fd8a23653', 'gw1.system.mode/000', 'Heating', 0, 'Normal operational mode. SCADA may actively energize and de-energize actuators in order to provide heating or cooling services. In this mode, SCADA may accept and execute Dispatch Contracts originating from the Leaf Transactive Node (LTN), subject to local safety constraints and configuration.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('56097ca4-7815-5281-7493-f4a46e6ab50b', 'gw1.system.mode/000', 'Standby', 1, 'Intentional idle mode with active inhibition. SCADA retains control authority over actuators but uses it only to prevent heating or cooling from occurring. This mode is typically used when the system is intentionally paused (e.g. seasonal shutdown, manual override, or safety condition) while still ensuring that uncontrolled equipment such as boilers or heat pumps do not engage.
') ON CONFLICT (enum_values_id) DO NOTHING;

INSERT INTO enum_values (enum_values_id, enum_version, symbol, idx, description)
VALUES ('0bce5fcc-d6e6-963e-a821-c7eba914f22e', 'gw1.system.mode/000', 'MonitorOnly', 2, 'Absolute non-actuation mode. SCADA MUST NOT issue any physical control actions, including relay changes or analog output updates. Telemetry collection, reporting, forecasting, and contract accounting may continue, but all actuators are left untouched. This mode provides a strong guarantee that no physical intervention will be performed by SCADA.
') ON CONFLICT (enum_values_id) DO NOTHING;

