INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('1c08eb88-d746-9430-d2bc-ab8e90e18c9d', 'g.node.gt', '004', 'https://schemas.electricity.works/types/g.node.gt/004', 'g.node.gt', 'A GNode (“Grid Node”) is the fundamental identity object in the GridWorks  ecosystem. Every physical location, metered unit, device, service, or actor  interacting with the transactive system is represented as a GNode.
', FALSE, NULL, '2026-02-24T14:00:00Z', '{"x-gridworks-extended_description": "Grid Nodes (GNodes) provide the stable identity layer for distributed coordination in the GridWorks ecosystem. Each GNode participates in a hierarchical alias structure that encodes topology, routing semantics, and coordination scope.\nGNodes may represent physical grid structure (e.g., metered boundaries, connectivity nodes, constraint points) or logical and service roles (e.g., SCADA agents, forecasting services, market participants). BaseClass defines the universal structural ontology required for interoperability. GNodeClass expresses organization-specific functional roles and does not alter structural semantics.\n`g.node.gt` is an immutable serialized snapshot of declared node state. Any change to a GNode (alias updates, status changes, relocations, or classification changes) SHALL be represented by publishing a new `g.node.gt` message rather than mutating a previously published instance. This preserves durable identity (GNodeId) while allowing controlled evolution of descriptive attributes.\nGNode is designed as the atomic unit of coordination in a recursively composable grid architecture. Systems of arbitrary scale are formed by composing GNodes into hierarchical or heterarchical structures. This allows optimal power flow (OPF), market clearing, and constraint coordination mechanisms to operate centrally, regionally, or in distributed configurations without altering the underlying identity model.\nConceptually, GNode aligns with node abstractions in IEC 61970/61968 CIM (e.g., ConnectivityNode and TopologicalNode), while unifying physical and logical coordination entities within a single identity abstraction suitable for graph-based modeling and transactive coordination.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('043a7ee2-8349-5d63-3539-fff5beb87509', 'g.node.instance.gt', '000', 'https://schemas.electricity.works/types/g.node.instance.gt/000', 'g.node.instance.gt', 'Durable snapshot of a runtime instance representing a Grid Node. Each instance record corresponds bijectively to a persistent FIS database record tracking runtime authority and transport connection state.
', FALSE, NULL, '2026-03-04T17:00:00Z', '{"x-gridworks-extended_description": "The g.node.instance.gt type represents a durable record of runtime authority for a Grid Node. It is maintained by the Fleet Index Service (FIS) and serves as an auditable snapshot of instance lifecycle events.\nWhile this type represents a single runtime instance, the broader system enforces a single-writer authority model: at most one instance per GNodeId is permitted to hold Status = Active at any time. That invariant is enforced at the runtime and database layer and is not validated within this schema itself.\nThe distinction between Active, Revoked, and Ended enables audit differentiation between normal shutdown, supersession by a newer instance, and forced authority revocation.\nConnectionHandle and ObservedPeerAddress are transport-observed values used for operational diagnostics and forensic analysis. Their structure is transport-specific and intentionally opaque to preserve neutrality across messaging systems.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('764ff2f9-2279-9620-996a-023ea33576d3', 'glitch', '000', 'https://schemas.electricity.works/types/glitch/000', 'glitch', 'An actor''s report of an unexpected or noteworthy runtime event, tagged with a logging severity. Glitches are raised by SCADA actors and forwarded up to the LeafTransactiveNode.
', FALSE, NULL, '2026-05-13T00:00:00Z', '{"x-gridworks-extended_description": "glitch is the actor-level mechanism by which a SCADA deployment reports unexpected or noteworthy runtime events. Actors call helpers such as send_critical, send_error, send_warning, and send_info, each of which builds a glitch tagged with the corresponding log.level Type and sends it toward the LeafTransactiveNode. A SCADA node relays glitches it receives from its actors onward to the LeafTransactiveNode, which broadcasts them.\nglitch is fire-and-forget: it is neither persisted nor acknowledged, so a glitch raised while the node is offline is lost.\ngridworks.event.problem covers similar ground from a different lineage -- it is inherited from the gwproactor framework rather than originating in GridWorks vocabulary. GridWorks expects to consolidate on glitch and retire gridworks.event.problem, and to add a companion glitch.event type for events that must be persisted and re-sent until acknowledged, so an operator can recover the error history after an internet outage.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('adcc8a6e-f8c8-3c15-7b62-e09c18f65388', 'gridworks.ack', '000', 'https://schemas.electricity.works/types/gridworks.ack', 'gridworks.ack', 'Versionless acknowledgement message used to confirm receipt of a prior GridWorks message by its message identifier.
', FALSE, NULL, NULL, '{"IsVersionless": true}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('f972ec20-8e89-4395-fd1d-92f7269c4631', 'gridworks.event.problem', '001', 'https://schemas.electricity.works/types/gridworks.event.problem/001', 'gridworks.event.problem', 'Event message reporting a problem detected in a GridWorks node.
', FALSE, NULL, '2026-05-13T00:00:00Z', '{"x-gridworks-extended_description": "gridworks.event.problem is inherited from the gwproactor framework rather than originating in GridWorks'' own vocabulary. Driver and sensor actors raise it through the framework''s Problems class -- typically Problems(warnings=..., errors=...).problem_event(...) -- as part of the proactor event stream.\nIt overlaps in purpose with glitch, GridWorks'' own actor-level event report. GridWorks expects to transition away from gridworks.event.problem, keeping glitch and adding a companion glitch.event type for events that must be persisted and re-sent until acknowledged.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('0fd53061-d55c-1d9a-25d9-4d2734ce6865', 'gridworks.ping', '000', 'https://schemas.electricity.works/types/gridworks.ping', 'gridworks.ping', 'Versionless message used for liveness and heartbeat checks between GridWorks components.
