INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('15719e36-6e1a-c14d-4c02-838bb38ef3d5', 'gw.nolan.layout', '000', 'https://schemas.electricity.works/draft/types/gw.nolan.layout/000', 'gw.nolan.layout', 'A complete, self-contained configuration and topology snapshot for a Nolan hydronic space heating system. The layout binds together identity (GNodes), operational topology (ShNodes), telemetry (DataChannels and DerivedChannels), hardware components, and actor configurations into a single semantically consistent structure.
This type is intended to be a deployable artifact. All referenced entities required for SCADA operation and coordination SHALL be present within the layout, enabling validation and execution without external registry access.
', FALSE, 'draft', '2026-03-20T19:00:00Z', '{"x-gridworks-extended_description": "TODO: add Nolan specific information (e.g. radiant floor heating, Gw108).\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

