INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('8e32ad47-2dd3-50ed-6ef4-f94b35e6be06', 'gw1.telemetry.name.quantity.projection', '000', 'https://schemas.electricity.works/types/gw1.telemetry.name.quantity.projection/000', 'telemetry.name.quantity.projection', 'Canonical projection from spaceheat.telemetry.name to gw1.quantity.
This type declares the deterministic semantic relationship by which every legacy Spaceheat telemetry encoding maps to exactly one gw1.quantity value.
It exists to support safe transition from TelemetryName-based dimensional encoding toward explicit gw1.unit and gw1.quantity separation.
', FALSE, NULL, '2026-03-16T14:14:56Z', NULL, NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('b2049239-7cf8-acec-dbf8-a1ac2af4424c', 'gw1.unit.quantity.projection', '000', 'https://schemas.electricity.works/types/gw1.unit.quantity.projection/000', 'gw1.unit.quantity.projection', 'Canonical projection from gw1.unit to gw1.quantity. This type declares the deterministic semantic relationship by which every gw1.unit maps to exactly one gw1.quantity.
The projection defines the physical dimension abstraction associated with each unit and ensures consistent dimensional reasoning across telemetry, derived channels, and market contracts.
', FALSE, NULL, '2026-03-04T19:00:00Z', NULL, NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

