INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('43ad9bd7-c2e9-36f4-f409-3c836766893a', 'latest.price', '000', 'https://schemas.electricity.works/types/latest.price/000', 'latest.price', 'Latest cleared market price for a given market slot, published by the MarketMaker responsible for that slot''s market. It reports the most recent real-time price observed for the identified slot so that downstream consumers can value energy, validate dispatch contracts, and record price history.
', FALSE, NULL, '2026-05-13T00:00:00Z', '{"x-gridworks-extended_description": "latest.price is the boundary message that announces a settled price for one market slot. In the intended architecture it is emitted by the MarketMaker that runs the market for that slot. Until a MarketMaker is deployed, a LeafTransactiveNode emits latest.price itself: at the start of each slot it resolves the real-time price and publishes it, and its contract handler uses the value, together with the node''s outstanding bid, to determine the energy commitment implied by an active dispatch contract. The message is also suitable for forwarding to a SCADA node so that the price series can be persisted alongside telemetry.\nlatest.price is a point-in-time notification, not a forecast: it reports one settled price for one slot. Forward-looking price expectations are carried by separate forecast types consumed by the optimization layer.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('b4e4acf5-420e-6884-7568-1df035d3187d', 'layout.lite', '007', 'https://schemas.electricity.works/types/layout.lite/007', 'layout.lite', 'Runtime projection of the active SCADA context needed to interpret telemetry and snapshot messages for a running Spaceheat deployment.
`layout.lite` is emitted by SCADA on request. It is not intended to be a lossless copy of the source layout artifact on disk. Some fields are projected directly from the loaded hardware layout, while others reflect active runtime settings.
', FALSE, NULL, '2026-01-14T14:08:00Z', '{"x-gridworks-extended_description": "`layout.lite` is the SCADA-emitted semantic context for a running deployment. It exists so consumers can interpret compact runtime payloads that reference channels and nodes by name rather than embedding full definitions in every message.\nIn particular, `report.event` and `snapshot.spaceheat` rely on `layout.lite` for channel interpretation. `ChannelName` references inside those messages SHALL be resolved against `DataChannels` and `DerivedChannels` in the relevant `layout.lite` context.\n`layout.lite` also carries selected runtime settings whose values affect the interpretation of the running system, including active HA1 parameters.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('9bb4a907-a29e-cce8-6483-6d55aa98720d', 'layout.lite', '008', 'https://schemas.electricity.works/types/layout.lite/008', 'layout.lite', 'Runtime projection of the active SCADA context needed to interpret telemetry and snapshot messages for a running Spaceheat deployment.
`layout.lite` is emitted by SCADA on request. It is not intended to be a lossless copy of the source layout artifact on disk. Some fields are projected directly from the loaded hardware layout, while others reflect active runtime settings.
', FALSE, NULL, '2026-01-15T18:00:00Z', '{"x-gridworks-extended_description": "`layout.lite` is the SCADA-emitted semantic context for a running deployment. It exists so consumers can interpret compact runtime payloads that reference channels and nodes by name rather than embedding full definitions in every message.\nIn particular, `report.event` and `snapshot.spaceheat` rely on `layout.lite` for channel interpretation. `ChannelName` references inside those messages SHALL be resolved against `DataChannels` and `DerivedChannels` in the relevant `layout.lite` context.\n`layout.lite` also carries selected runtime settings whose values affect the interpretation of the running system, including system mode, seasonal storage mode, short-cycling behavior, and active HA1 parameters.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

