INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('57483089-cfdd-2712-9569-8e32d7eed0e0', 'linear.one.dimensional.calibration', '000', 'https://schemas.electricity.works/types/linear.one.dimensional.calibration/000', 'linear.one.dimensional.calibration', 'Linear calibration applied to a raw sensor measurement.
The transformation is interpreted as:

    calibrated_value = M * raw_value + B

This type represents empirical correction of a sensor''s raw output into a physically meaningful quantity.
', FALSE, NULL, '2026-02-06T17:06:00Z', NULL, NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('cdb64c08-8af0-5364-b3ca-5dabbf5cbbd1', 'linear.one.dimensional.calibration', '001', 'https://schemas.electricity.works/types/linear.one.dimensional.calibration/001', 'linear.one.dimensional.calibration', 'Linear calibration applied to a measurement expressed in the derived channel''s declared OutputUnit domain.
The transformation is interpreted as:

    calibrated = M * x + B

where:

  - x is the input measurement first converted into the OutputUnit
    scaling of the derived channel.

  - M is dimensionless.

  - B is expressed in OutputUnit scaling and therefore shares the
    same integer scaling convention as the derived channel''s output.

This type represents an affine correction applied after unit normalization and does not itself declare units.
', FALSE, NULL, '2026-03-16T20:55:00Z', '{"x-gridworks-extended_description": "Instances of this type are typically used as Parameters for derived.channel.gt when Strategy equals \"affine\".\nThe calibration is interpreted in the OutputUnit scaling domain declared by the referencing derived channel."}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('3e2b34b9-f6a2-6043-082c-37f912c219fe', 'machine.states', '000', 'https://schemas.electricity.works/types/machine.states/000', 'machine.states', 'Sequence of machine states observed for one state machine during a reporting interval.
', FALSE, NULL, '2024-11-09T16:36:00Z', NULL, NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('c9a093c3-6793-1bd6-b3ec-65486d5bac60', 'new.command.tree', '000', 'https://schemas.electricity.works/types/new.command.tree/000', 'new.command.tree', 'Full set of SpaceheatNodes describing a SCADA node''s current actor command hierarchy, sent by the SCADA node to its LeafTransactiveNode. Each node carries the handle that locates it in the command tree; receiving a new.command.tree replaces the recipient''s prior view of that hierarchy in its entirety.
', FALSE, NULL, '2026-05-13T00:00:00Z', '{"x-gridworks-extended_description": "A GridWorks SCADA node owns the hardware layout and the actor hierarchy that commands it. When that hierarchy changes -- for example when control is handed between automatic and administrative bosses -- the SCADA node sends a new.command.tree to its LeafTransactiveNode so the LTN''s view of who commands whom stays current.\nThe message is a full snapshot rather than a delta: the recipient discards its previous command tree and adopts ShNodes as the new one. The actor hierarchy is expressed through SpaceheatNode handles and ActorHierarchyNames, dotted strings whose prefixes name successive bosses. Axiom 1 makes this structural: each set is prefix-closed, so every boss referenced by a node is itself present in ShNodes.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
