INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('62107180-c712-17a5-19a3-508fefcf37ec', 'relay.actor.config', '002', 'https://schemas.electricity.works/types/relay.actor.config/002', 'relay.actor.config', 'Configuration for a relay-backed Spaceheat actor associated with one relay on a multi-channel relay board.
A relay.actor.config binds a specific relay index on a relay component to a named actor and declares the event/state semantics associated with energizing and de-energizing that relay. The config also carries the channel capture settings required to report the relay-controlled actor''s state into the telemetry system.
', FALSE, NULL, '2024-12-31T15:38:00Z', '{"x-gridworks-extended_description": "relay.actor.config specializes generic channel capture configuration for relay-backed actors in hydronic control systems.\nThis type binds one relay position on a relay board to a specific actor and declares the event/state semantics associated with switching that relay. These semantics are important for distributed coordination because different layouts may realize the same functional role using different underlying hardware node names, while preserving identical actor-level meaning.\nTypical uses include selecting the source of a heat call, enabling or disabling control authority, or switching physical flow or heating elements between named operating states.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('8df6ec7e-7b3f-97c0-8b39-1e95e42e2998', 'relay.actor.config', '003', 'https://schemas.electricity.works/types/relay.actor.config/003', 'relay.actor.config', 'Configuration for a relay-backed Spaceheat actor associated with one relay on a multi-channel relay board.
A relay.actor.config binds a specific relay index on a relay component to a named actor and declares the event/state semantics associated with energizing and de-energizing that relay. The config also carries the channel capture settings required to report the relay-controlled actor''s state into the telemetry system.
', FALSE, NULL, '2026-04-01T10:49:00Z', '{"x-gridworks-extended_description": "relay.actor.config specializes generic channel capture configuration for relay-backed actors in hydronic control systems.\nThis type binds one relay position on a relay board to a specific actor and declares the event/state semantics associated with switching that relay. These semantics are important for distributed coordination because different layouts may realize the same functional role using different underlying hardware node names while preserving identical actor-level meaning.\nIn this registry, the declared relay event/state semantics are based on change.relay.state and relay.closed.or.open.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('2e42b5af-1227-f76b-0309-13b52217b1e6', 'report', '002', 'https://schemas.electricity.works/types/report/002', 'report', 'Primary telemetry and state reporting message produced by a SCADA node for a specific reporting slot. A report contains all meaningful channel readings, state transitions, and FSM outputs observed during the slot period.
', FALSE, NULL, '2025-04-23T18:03:00Z', '{"x-gridworks-extended_description": "Reports are sent at fixed slot intervals (typically 5 minutes) and provide a durable historical record of telemetry and state changes observed during that period.\nGridWorks SCADA devices emit most channel readings asynchronously when values change beyond configured thresholds. Each reading is timestamped at the moment of observation by the SCADA device. Reports preserve these original timestamps without resampling or aggregation.\nAs a result, a report represents a batched event log for the slot period rather than a sampled snapshot. Consumers can reconstruct the precise timing of state transitions (e.g., relay changes) and value updates within the slot window.\nThis differs from snapshot messages, which represent the most recent value of each channel at a single point in time and are optimized for near-real-time visualization rather than historical accuracy.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('be9876e0-152c-c0e9-f40c-a56a6eb768fa', 'report', '003', 'https://schemas.electricity.works/types/report/003', 'report', 'Historical telemetry and state report for a fixed reporting interval. A Report contains all meaningful channel readings and machine state transitions observed during a single SlotDurationS window.
Reports are the authoritative historical record of SCADA behavior. They are emitted periodically (typically every 5 minutes) and contain timestamped readings for each channel that changed or reported during the interval.
', FALSE, NULL, '2026-03-30T19:01:47Z', '{"x-gridworks-extended_description": "Reports provide the durable historical record of SCADA telemetry. They differ from snapshots in that they preserve all timestamped readings within a fixed interval rather than only the most recent value.\nReports are optimized for replay, auditing, debugging, and analytics. Snapshots are optimized for real-time visualization.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

