VALUES ('6ea3cf3a-ea70-ab9e-9259-52bf50deef2c', 'scada.control.capabilities', '000', 'https://schemas.electricity.works/types/scada.control.capabilities/000', 'scada.control.capabilities', 'Projection of the control surface exposed by a SCADA node. This type declares controllable relay and DAC nodes, the telemetry channels that represent their observed state, and the relay semantic configuration required for dispatch construction.
This is a control-focused projection derived from layout.lite and does not represent the full system topology.
', FALSE, NULL, '2026-03-02T18:00:00Z', NULL, NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('063118bf-38f7-a382-7e74-43481bd4aa51', 'scada.control.capabilities', '001', 'https://schemas.electricity.works/types/scada.control.capabilities/001', 'scada.control.capabilities', 'Projection of the control surface exposed by a SCADA node. This type declares controllable relay and DAC nodes, the telemetry channels that represent their observed state, and the relay semantic configuration required for dispatch construction.
This is a control-focused projection derived from layout.lite and does not represent the full system topology.
', FALSE, NULL, '2026-05-07T20:00:00Z', NULL, NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('a05cb3f0-66c2-d801-7a88-349acc540d90', 'scada.params', '004', 'https://schemas.electricity.works/types/scada.params/004', 'scada.params', 'Message used to read or change the HA1 control parameters held by a SCADA node, exchanged between a LeafTransactiveNode and a SCADA node. A request carries the proposed NewParams; the SCADA node''s reply echoes the same MessageId and reports the parameters in effect before and after the change.
', TRUE, NULL, '2026-02-18T11:07:45Z', '{"x-gridworks-extended_description": "HA1 is the home-heating control algorithm run by a GridWorks SCADA node. scada.params is the boundary message for inspecting and updating the algorithm''s tuning parameters without redeploying the SCADA node.\nThe exchange is request/reply. A LeafTransactiveNode sends a scada.params with NewParams set to the parameters it wants applied. The SCADA node adopts them, then replies with a scada.params that echoes the request''s MessageId, sets OldParams to the values it had been running, and sets NewParams to the values now in effect. A request with NewParams absent reads the current parameters without changing them. NewParams and OldParams are optional because not every message in the exchange carries both.\nThe SCADA codebase held scada.params at version 004 across an ha1.params version bump, so version 004 messages were emitted carrying either an ha1.params version 004 or version 005 object. NewParams and OldParams therefore accept both, expressed as a oneOf of those two ha1.params versions; the ha1.params Version field discriminates which one a given message carries.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('ef914217-92b8-79bb-5add-87dace8645ae', 'scada.params', '005', 'https://schemas.electricity.works/types/scada.params/005', 'scada.params', 'Message used to read or change the HA1 control parameters held by a SCADA node, exchanged between a LeafTransactiveNode and a SCADA node. A request carries the proposed NewParams; the SCADA node''s reply echoes the same MessageId and reports the parameters in effect before and after the change.
', TRUE, NULL, '2026-02-25T19:23:45Z', '{"x-gridworks-extended_description": "HA1 is the home-heating control algorithm run by a GridWorks SCADA node. scada.params is the boundary message for inspecting and updating the algorithm''s tuning parameters without redeploying the SCADA node.\nThe exchange is request/reply. A LeafTransactiveNode sends a scada.params with NewParams set to the parameters it wants applied. The SCADA node adopts them, then replies with a scada.params that echoes the request''s MessageId, sets OldParams to the values it had been running, and sets NewParams to the values now in effect. A request with NewParams absent reads the current parameters without changing them. NewParams and OldParams are optional because not every message in the exchange carries both.\nVersion 005 differs from version 004 only in the referenced ha1.params version: version 004 carried ha1.params version 004 or 005, while version 005 carries ha1.params version 006. The commit that bumped scada.params to 005 is the same commit that introduced ha1.params version 006, so scada.params version 005 has only ever carried ha1.params version 006.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

