INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('87611735-af07-a585-9ded-dfedc9f6e7b1', 'spaceheat.node.gt', '200', 'https://schemas.electricity.works/types/spaceheat.node.gt/200', 'spaceheat.node.gt', 'A Spaceheat node representing a named element in the SCADA system.
', TRUE, NULL, '2026-01-14T14:08:00Z', '{"x-gridworks-extended_description": "Spaceheat nodes are the fundamental building blocks of an agent-based SCADA deployment for a hydronic heating system.\nEach node represents a named element in the operational control model. Nodes may correspond to active software actors responsible for sensing, control, telemetry generation, or coordination. They may also represent passive physical or logical entities that are measured or controlled, or higher-level semantic roles such as supervisory control, derived signals, or system modes.\nThis abstraction unifies physical equipment, software actors, and logical constructs under a single naming system, enabling consistent binding across telemetry, control, and coordination layers.\nThis type permits additionalProperties to support forward-compatible schema evolution and temporary inclusion of application-specific fields during layout development. Such extensions are expected to be formalized into explicit schema properties over time.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

