INSERT INTO type_versions (type_versions_id, type, version, schema_url, title, description, extra_allowed, status, created, raw_json, last_modified, promoted_at)
VALUES ('40b37ee9-4566-1141-96a3-f7fd27a56df7', 'synced.readings.bundle', '001', 'https://schemas.electricity.works/types/synced.readings.bundle/001', 'synced.readings.bundle', 'Time-aligned sequence of synchronized multi-channel readings with embedded channel semantics sufficient for independent interpretation.
For each channel, values in its associated ValueList are ordered to align by index with TimestampList, such that the value at index i corresponds to TimestampList[i].
ChannelDefinitions provides the measurement unit required to interpret values for each channel.
', FALSE, NULL, '2026-04-03T16:00:00Z', '{"x-gridworks-extended_description": "\n`synced.readings.bundle` represents a rectangular, time-aligned dataset across multiple channels.\nChannelName values are identifiers defined within a GridWorks SCADA layout context (e.g. layout.lite or gw.nolan.layout). They are not globally standardized vocabulary and SHALL be interpreted only within the context in which they were produced.\nChannelDefinitions provides a minimal projection of channel semantics, including `Name`, `Id`, `Unit` and `UnitType`, sufficient to interpret the numeric values in this bundle without requiring access to the full layout.\nThe `Id` together with the channel TypeName (e.g. `data.channel.gt`, `derived.channel.gt`, or `analytics.channel.gt`) enables resolution of the authoritative channel definition. This bundle is not a source of semantic authority; it provides a convenient projection for transport, indexing, and querying.\nIn GridWorks systems, full channel definitions are typically available in layout artifacts such as `layout.lite`, which include additional information such as `AboutNodeName`, `CapturedByNodeName`, and derivation strategy. Those details are intentionally omitted here to keep this type lightweight and focused on boundary interpretation.\nAll channels share a common `TimestampList`. For any index i, values across all channels correspond to the same point in time.\n"}', NULL, NULL) ON CONFLICT (type_versions_id) DO NOTHING;

