-- ----------------------------------------------------------------------------
-- TypeAxioms: Per-TypeVersion axioms (numbered invariants stated in natural language). Sourced from x-gridworks.axioms in YAML.
-- ----------------------------------------------------------------------------
INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('b4c9627d-5542-a561-55ed-637ee7f3f517', 'analytics.channel.gt/000', 1, 'OutputUnitQuantityConsistency', 'OutputQuantity SHALL equal the Quantity defined by the canonical gw1.float.unit.quantity.projection/000 instance for the specified OutputUnit.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('2ce20c51-e0f1-f291-19a6-8a93bf709415', 'atn.bid/002', 1, 'PqPairsPriceMaxMatchesMarketType', 'The first price in PqPairs SHALL equal the PriceMax defined by the MarketType associated with MarketSlotName.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('6a384c07-fa29-3886-0709-d7024d67b04a', 'bid/000', 1, 'MarketNormalizationAnchor', 'The price of the first element in PqPairs SHALL equal the PriceMax defined by the MarketType associated with MarketSlotName.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('4d1d654e-35b2-da49-f622-5078ea7b6598', 'bid/000', 2, 'UnitConsistency', 'PriceUnit and QuantityUnit SHALL match the units declared by the MarketType associated with MarketSlotName.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('bc425738-cb94-5afd-0972-60dd113a9f8d', 'bid/000', 3, 'CurveAdmissibility', 'The structure, ordering, and cardinality of PqPairs SHALL conform to the admissibility rules of the MarketType associated with MarketSlotName (including any constraints on price ordering, monotonicity, tick size, or maximum number of segments).
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('38f76d8e-d8ed-b5a5-dd7c-a4a267e658bd', 'bid/000', 4, 'EconomicAdmission', 'SignedMarketFeeTxn MUST be verifiable under the market’s fee and admission policy for the specified MarketSlot.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('0f8d8810-f590-20f9-c616-206563315153', 'channel.config/000', 1, 'CaptureAndPollingConsistency', 'If PollPeriodMs is present, then CapturePeriodMs (CapturePeriodS * 1000) SHALL be greater than PollPeriodMs. If CapturePeriodMs is less than 10 times PollPeriodMs, then CapturePeriodMs SHALL be a multiple of PollPeriodMs.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('f3a98f1e-3acd-05fc-29d4-ce5808605a50', 'channel.readings/001', 1, 'ListLengthConsistency', 'len(ValueList) SHALL equal len(ScadaReadTimeUnixMsList).
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('e70aa269-b36f-19da-3583-b1e4acc1b408', 'channel.readings/002', 1, 'ListLengthConsistency', 'len(ValueList) SHALL equal len(ScadaReadTimeUnixMsList).
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('74357477-a08e-b740-d9b1-c6c1bfb8bc42', 'connectivity.edge.gt/000', 1, 'NoSelfLoop', 'FromGNodeId SHALL NOT equal ToGNodeId.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('355184b5-0188-a1e9-b8b3-e629391819d0', 'data.channel.gt/001', 1, 'PowerMeteringConstraint', 'If InPowerMetering is true, TelemetryName SHALL equal PowerW.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('74fc5867-462a-4887-af1a-431ac607fe89', 'data.channel.gt/002', 1, 'PowerMeteringConstraint', 'If InPowerMetering is true, TelemetryName SHALL equal PowerW.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('27ce082c-d58e-23ab-467a-181fc4801b3c', 'data.channel.gt/002', 2, 'TelemetryQuantityConsistency', 'Quantity SHALL equal the Quantity defined by the canonical spaceheat.telemetry.quantity.projection/000 instance for the specified TelemetryName.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('0d757fe9-e554-78c2-7139-52dfeba4fa1c', 'derived.channel.gt/001', 1, 'EmissionSemanticsConsistency', 'EmissionMethod SHALL determine the presence of EmitPeriodS and AsyncEmitDelta as follows:

  OnTrigger → neither EmitPeriodS nor AsyncEmitDelta present
  Periodic → EmitPeriodS present, AsyncEmitDelta absent
  AsyncAndPeriodic → both EmitPeriodS and AsyncEmitDelta present
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('30f6bcc1-eb7a-605a-40b5-8fb061a5318d', 'derived.channel.gt/002', 1, 'EmissionSemanticsConsistency', 'EmissionMethod SHALL determine the presence of EmitPeriodS and AsyncEmitDelta as follows:

  OnTrigger → neither EmitPeriodS nor AsyncEmitDelta present
  Periodic → EmitPeriodS present, AsyncEmitDelta absent
  AsyncAndPeriodic → both EmitPeriodS and AsyncEmitDelta present
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('df46db3a-7346-1bda-88d5-5b9410409e03', 'derived.channel.gt/002', 2, 'OutputUnitQuantityConsistency', 'OutputQuantity SHALL equal the Quantity defined by the canonical gw1.unit.quantity.projection:000 instance for the specified OutputUnit.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('be557223-820f-6656-f23a-786fc634551d', 'derived.channel.gt/002', 3, 'AffineStrategyRequiresCalibration', 'If Strategy equals "affine", then:

  - Parameters SHALL contain a key "Calibration".
  - Parameters.Calibration SHALL be a valid
    linear.one.dimensional.calibration instance.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('52260a2e-326e-c29a-7ae3-000bd2ccd6c7', 'derived.channel.gt/002', 4, 'SystemModelRequiresParameters', 'If Strategy equals "system-model", then:
  - Parameters SHALL be present.
  - Parameters SHALL contain a key "EnergyModel".
  - Parameters.EnergyModel SHALL include:
      - TypeName
      - Version
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('3a486816-a04e-dfa7-717e-77d61bbc039e', 'energy.instruction/000', 1, 'SlotStartOnMinuteBoundary', 'SlotStartS SHALL be divisible by 60.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('3e4367ce-11ad-7818-0199-5b422e75d5d0', 'energy.instruction/000', 2, 'SendTimeProximityToSlotStart', 'SendTimeMs SHALL be no more than 10 seconds after SlotStartS * 1000.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('a7bb9738-d4e5-0e3e-e917-4b0e6845764b', 'fis.authority.manifest/000', 1, 'InstanceReferenceIntegrity', 'For every element in GNodeInstanceList, there SHALL exist exactly one element in GNodeList whose GNodeId matches the instance''s GNodeId.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('e62cbe85-e700-eeb1-f35b-3153abf4040a', 'fis.authority.manifest/000', 2, 'SingleActiveInstancePerGNode', 'For each element in GNodeList, exactly one element in GNodeInstanceList SHALL have matching GNodeId and Status equal to Active.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('7cc990ef-e104-66f9-5039-c28feb332f06', 'fis.authority.manifest/000', 3, 'ParentClosureUpToDeclaredRoots', 'For every element in GNodeList, all alias prefixes of GNodeAlias SHALL also appear in GNodeList unless the prefix equals one of the aliases listed in ParentRootAliasList.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('b7c779fc-8e74-f296-cc24-fa47b0645936', 'fsm.atomic.report/000', 1, 'ActionPresenceConsistency', 'Action and ActionType SHALL be present if and only if ReportType equals Action.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('c6b905ec-91db-6fd5-f065-3f241cdc5b60', 'fsm.atomic.report/000', 2, 'ActionTypeConsistency', 'If Action is present, ActionType SHALL also be present.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('4cb64b83-9f95-97e1-f647-1d35e6a42362', 'fsm.atomic.report/000', 3, 'EventPresenceConsistency', 'EventEnum, Event, FromState, and ToState SHALL be present if and only if ReportType equals Event.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('33cd9e16-cc36-9eea-5733-5ed215efc694', 'fsm.atomic.report/001', 1, 'ActionPresenceConsistency', 'Action SHALL be present if and only if ReportType equals Action.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('ccabc948-8a60-d931-b177-75f12ad09648', 'fsm.atomic.report/001', 2, 'EventPresenceConsistency', 'EventEnum, Event, FromState, and ToState SHALL be present if and only if ReportType equals Event.
') ON CONFLICT (type_axioms_id) DO NOTHING;

