INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('0b52d37f-86c3-3d4b-587c-5855dcb8c7f7', 'machine.states/000', 1, 'ListLengthConsistency', 'len(StateList) SHALL equal len(UnixMsList).
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('3d5b2b82-e58c-3f79-f1c0-c63eac40c7bf', 'machine.states/000', 2, 'RecognizedStateEnumConsistency', 'If StateEnum is a recognized GridWorks enum, then all elements of StateList SHALL be valid values of that enum.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('70033a98-7c53-cce6-7def-7613f68b2877', 'new.command.tree/000', 1, 'PrefixClosedHierarchy', 'a. The set of ShNode Handles SHALL be prefix-closed: for every ShNode in ShNodes whose Handle is present, each of its dot-separated prefixes SHALL also be the Handle of some ShNode in ShNodes.
b. The set of ShNode ActorHierarchyNames SHALL be prefix-closed in the same way: for every ShNode in ShNodes whose ActorHierarchyName is present, each of its dot-separated prefixes SHALL also be the ActorHierarchyName of some ShNode in ShNodes.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('f04d52df-025d-a87c-7b8d-afb5baa62c7d', 'pico.flow.module.component.gt/000', 1, 'HwUidPattern', 'If HwUid is present, it SHALL match the pattern pico_xxxxxx where xxxxxx consists of six lowercase hexadecimal characters.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('ed8675a8-dbdb-84d1-b724-fa9e29dd3a8e', 'pico.tank.module.component.gt/011', 1, 'PicoHardwareIdentityXor', 'Exactly one of the following SHALL hold:
  - PicoHwUid is present
  - both PicoAHwUid and PicoBHwUid are present
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('0d1a49d3-a721-bef7-0e62-c89f33d29ff9', 'pico.tank.module.component.gt/011', 2, 'PicoKOhmsConsistency', 'PicoKOhms SHALL be present if and only if TempCalcMethod equals SimpleBetaForPico.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('e39b7f47-83a9-6108-e5a0-2c272fdba956', 'pico.tank.module.component.gt/011', 3, 'SensorOrderPermutation', 'If SensorOrder is present, it SHALL be a permutation of [1, 2, 3].
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('49b415a3-e4aa-6633-41ac-85f4e4aa9302', 'position.point.gt/000', 1, 'ValidEarthCoordinates', 'LatitudeMicroDeg SHALL be between -90,000,000 and 90,000,000 inclusive. LongitudeMicroDeg SHALL be between -180,000,000 and 180,000,000 inclusive.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('70e9323c-25d8-5717-e97a-162fca6c9979', 'relay.actor.config/002', 1, 'EventEnumConsistency', 'If EventType names a known enum, then DeEnergizingEvent and EnergizingEvent SHALL both be valid values of that enum.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('55b067de-aa45-61ac-2cac-efcc06abb0ac', 'relay.actor.config/002', 2, 'StateEnumConsistency', 'If StateType names a known enum, then DeEnergizedState and EnergizedState SHALL both be valid values of that enum.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('0e440fad-859b-0757-7817-6869fb5c216c', 'relay.actor.config/002', 3, 'EventStateSemanticMatch', 'EnergizingEvent and DeEnergizingEvent SHALL correspond semantically to transitions into EnergizedState and DeEnergizedState respectively.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('d8034fc5-db4a-0237-6950-9d35272f4c6b', 'relay.actor.config/002', 4, 'ClosedOpenWiringConsistency', 'If:

  - StateType equals "relay.closed.or.open"
  - EventType equals "change.relay.state"
  - WiringConfig equals "NormallyClosed"

then:

  - DeEnergizedState SHALL equal "RelayClosed"
  - DeEnergizingEvent SHALL equal "CloseRelay"
  - EnergizedState SHALL equal "RelayOpen"
  - EnergizingEvent SHALL equal "OpenRelay"

If:

  - StateType equals "relay.closed.or.open"
  - EventType equals "change.relay.state"
  - WiringConfig equals "NormallyOpen"

then:

  - DeEnergizedState SHALL equal "RelayOpen"
  - DeEnergizingEvent SHALL equal "OpenRelay"
  - EnergizedState SHALL equal "RelayClosed"
  - EnergizingEvent SHALL equal "CloseRelay"
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('3ad29fa0-5d55-05c5-1e67-b1d45493cf61', 'relay.actor.config/003', 1, 'AsyncCaptureConsistency', 'If AsyncCapture is true, then AsyncCaptureDelta SHALL be present.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('ce32bcd3-e1af-213f-2aae-c8337f14ede0', 'relay.actor.config/003', 2, 'CapturePollingConsistency', 'If PollPeriodMs is present, then CapturePeriodMs (CapturePeriodS * 1000) SHALL be greater than PollPeriodMs. If CapturePeriodMs is less than 10 times PollPeriodMs, then CapturePeriodMs SHALL be a multiple of PollPeriodMs.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('150b1f4c-8182-a61c-6bfd-c54a8919cb27', 'relay.actor.config/003', 3, 'RelayEventEnumConsistency', 'If EventType equals "change.relay.state", then DeEnergizingEvent and EnergizingEvent SHALL both be valid values of change.relay.state:000.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('db7ad620-fb2b-cb7c-60af-9968cb608bd6', 'relay.actor.config/003', 4, 'RelayStateEnumConsistency', 'If StateType equals "relay.closed.or.open", then DeEnergizedState and EnergizedState SHALL both be valid values of relay.closed.or.open:000.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('053f538c-77a8-c6ac-66c7-4d27f1b57cda', 'relay.actor.config/003', 5, 'RelayEventStateMatch', 'If EventType equals "change.relay.state" and StateType equals "relay.closed.or.open", then:

  - DeEnergizingEvent "CloseRelay" SHALL imply DeEnergizedState "RelayClosed"
  - DeEnergizingEvent "OpenRelay" SHALL imply DeEnergizedState "RelayOpen"
  - EnergizingEvent "CloseRelay" SHALL imply EnergizedState "RelayClosed"
  - EnergizingEvent "OpenRelay" SHALL imply EnergizedState "RelayOpen"
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('cd02c2e6-7273-384f-11ae-74c44b1d3b85', 'report.event/002', 1, 'ReportIdentityPropagation', 'MessageId SHALL equal Report.Id.
') ON CONFLICT (type_axioms_id) DO NOTHING;

INSERT INTO type_axioms (type_axioms_id, type_version, number, axiom_name, statement)
VALUES ('1f51c023-bf35-5e3c-984e-6f26eca43e48', 'report.event/002', 2, 'ReportCreatedTimePropagation', 'TimeCreatedMs SHALL equal Report.MessageCreatedMs.
') ON CONFLICT (type_axioms_id) DO NOTHING;

